import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import {
  Activity, ArrowLeft, ArrowRight, BarChart3, Bell, Bot, Check, CheckCircle2, ChevronDown,
  Clock3, FileCheck2, FileText, Filter, Home, Info, LayoutList, LifeBuoy, LockKeyhole,
  LogOut, Menu, MessageSquare, MoreHorizontal, Paperclip, Plus, Search, Send, ShieldCheck,
  Sparkles, TrendingUp, UploadCloud, UserRound, X, AlertTriangle
} from 'lucide-react';
import { Route, Switch, Router as WouterRouter, Link, useLocation, useParams } from 'wouter';
import { useEffect, useState } from 'react';
import {
  useRegister, useLogin, useGetCurrentUser, useGetCustomerDashboard, useListApplications,
  useCreateApplication, useGetApplication, useListDocuments, useAddDocument, useSubmitApplication,
  useGetDecision, useUpdateDecision, useListStatusHistory, useGetUnderwriterDashboard,
  useListUnderwriterApplications, useGetAnalytics, useSendChatMessage
} from '@workspace/api-client-react';
import type { Application, Decision, Document, StatusEvent } from '@workspace/api-client-react';
import { getGetApplicationQueryKey, getListDocumentsQueryKey, getGetDecisionQueryKey, getListStatusHistoryQueryKey } from '@workspace/api-client-react';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const money = (n?: number | null) => typeof n === 'number' ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(n) : '—';
const date = (s?: string | null) => s ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(s)) : '—';
const initials = (name?: string) => (name || 'Guest').split(' ').map((x) => x[0]).join('').slice(0, 2).toUpperCase();

function Logo({ light = false }: { light?: boolean }) {
  return <Link href="/dashboard" className="flex items-center gap-3" data-testid="link-brand">
    <span className={`grid size-9 place-items-center rounded-xl ${light ? 'bg-[hsl(var(--accent))] text-[hsl(var(--sidebar))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`}>
      <ShieldCheck size={19} strokeWidth={2.4} />
    </span>
    <span className={`font-serif text-lg font-bold tracking-tight ${light ? 'text-[hsl(var(--sidebar-foreground))]' : 'text-[hsl(var(--foreground))]'}`}>Aegisline</span>
  </Link>;
}

function StatusPill({ status }: { status?: string }) {
  const s = (status || 'pending').toLowerCase();
  const styles: Record<string, string> = {
    approved: 'bg-emerald-100 text-emerald-800 border-emerald-200',
    declined: 'bg-rose-100 text-rose-800 border-rose-200',
    'in review': 'bg-amber-100 text-amber-800 border-amber-200',
    submitted: 'bg-sky-100 text-sky-800 border-sky-200',
    draft: 'bg-slate-100 text-slate-700 border-slate-200',
    pending: 'bg-amber-100 text-amber-800 border-amber-200',
  };
  return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-semibold capitalize ${styles[s] || styles.pending}`} data-testid={`status-${s.replaceAll(' ', '-')}`}>
    <span className="size-1.5 rounded-full bg-current opacity-70" />{status || 'Pending'}
  </span>;
}

function PageLoader() {
  return <div className="space-y-5 animate-pulse" data-testid="loading-page"><div className="h-8 w-56 rounded-lg bg-muted" /><div className="h-28 rounded-2xl bg-muted" /><div className="grid gap-4 md:grid-cols-3"><div className="h-32 rounded-2xl bg-muted" /><div className="h-32 rounded-2xl bg-muted" /><div className="h-32 rounded-2xl bg-muted" /></div></div>;
}
function ErrorState({ retry }: { retry?: () => void }) {
  return <div className="rounded-2xl border border-rose-200 bg-rose-50 p-8 text-center" data-testid="state-error"><AlertTriangle className="mx-auto mb-3 text-rose-600" /><h3 className="font-serif text-lg font-bold text-rose-950">We could not load this view</h3><p className="mt-1 text-sm text-rose-800">Please try again. Your saved information is safe.</p>{retry && <button onClick={retry} className="mt-4 rounded-lg bg-rose-700 px-4 py-2 text-sm font-semibold text-white" data-testid="button-retry">Try again</button>}</div>;
}
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: React.ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card p-12 text-center" data-testid="state-empty"><div className="mx-auto mb-4 grid size-12 place-items-center rounded-2xl bg-secondary text-primary"><FileText size={21} /></div><h3 className="font-serif text-lg font-bold">{title}</h3><p className="mx-auto mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p>{action}</div>;
}

function Shell({ children, user }: { children: React.ReactNode; user?: { name: string; email: string; role: string } }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [location] = useLocation();
  const role = user?.role === 'underwriter' || user?.role === 'admin' ? 'underwriter' : 'customer';
  const nav = role === 'underwriter'
    ? [{ href: '/dashboard', label: 'Overview', icon: Home }, { href: '/underwriter', label: 'Review queue', icon: LayoutList }, { href: '/analytics', label: 'Portfolio analytics', icon: BarChart3 }, { href: '/chat', label: 'Policy assistant', icon: MessageSquare }]
    : [{ href: '/dashboard', label: 'Overview', icon: Home }, { href: '/applications', label: 'My applications', icon: FileCheck2 }, { href: '/applications/new', label: 'New application', icon: Plus }, { href: '/chat', label: 'Policy assistant', icon: MessageSquare }];
  return <div className="min-h-[100dvh] bg-background text-foreground">
    <aside className={`fixed inset-y-0 left-0 z-30 flex w-64 flex-col bg-sidebar p-5 transition-transform md:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="mb-10 flex items-center justify-between"><Logo light /><button className="text-sidebar-foreground md:hidden" onClick={() => setMobileOpen(false)} data-testid="button-close-menu"><X size={19} /></button></div>
      <div className="mb-5 px-3 text-[10px] font-bold uppercase tracking-[0.18em] text-sidebar-foreground/45">{role === 'underwriter' ? 'Underwriting desk' : 'Your cover'}</div>
      <nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={`group flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium transition-colors ${location === href || (href !== '/dashboard' && location.startsWith(href)) ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground'}`} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={17} /><span>{label}</span>{href === '/underwriter' && <span className="ml-auto rounded-full bg-accent px-2 py-0.5 text-[10px] font-bold text-accent-foreground">12</span>}</Link>)}</nav>
      <div className="mt-auto space-y-4">
        <div className="rounded-2xl border border-sidebar-border bg-sidebar-accent/50 p-4"><div className="mb-2 flex items-center gap-2 text-xs font-semibold text-sidebar-foreground"><LockKeyhole size={13} className="text-sidebar-primary" /> Trusted workspace</div><p className="text-[11px] leading-relaxed text-sidebar-foreground/55">Decisions are explainable, reviewable, and yours to question.</p></div>
        <Link href="/login" className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-sidebar-foreground/60 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="link-sign-out"><LogOut size={17} /> Sign out</Link>
      </div>
    </aside>
    {mobileOpen && <button className="fixed inset-0 z-20 bg-[hsl(var(--sidebar))]/30 md:hidden" onClick={() => setMobileOpen(false)} aria-label="Close menu" data-testid="button-overlay-menu" />}
    <main className="md:pl-64">
      <header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-border/70 bg-background/90 px-5 backdrop-blur md:px-10">
        <button className="text-muted-foreground md:hidden" onClick={() => setMobileOpen(true)} data-testid="button-open-menu"><Menu size={21} /></button>
        <div className="hidden items-center gap-2 text-xs text-muted-foreground md:flex"><span className="size-2 rounded-full bg-emerald-500" /> Secure workspace <span className="mx-1 text-border">/</span> {role === 'underwriter' ? 'Underwriting' : 'Customer portal'}</div>
        <div className="ml-auto flex items-center gap-4"><button className="relative text-muted-foreground hover:text-foreground" data-testid="button-notifications"><Bell size={18} /><span className="absolute -right-1 -top-1 size-1.5 rounded-full bg-accent" /></button><div className="flex items-center gap-2.5 border-l border-border pl-4"><span className="grid size-8 place-items-center rounded-full bg-primary text-[11px] font-bold text-primary-foreground" data-testid="avatar-user">{initials(user?.name)}</span><span className="hidden text-sm font-semibold sm:block" data-testid="text-user-name">{user?.name || 'Workspace user'}</span><ChevronDown size={14} className="text-muted-foreground" /></div></div>
      </header>
      <div className="mx-auto max-w-[1440px] p-5 md:p-10">{children}</div>
    </main>
  </div>;
}

function AuthLayout({ children, mode }: { children: React.ReactNode; mode: 'login' | 'register' }) {
  return <div className="grid min-h-[100dvh] bg-background lg:grid-cols-[0.9fr_1.1fr]">
    <section className="relative hidden overflow-hidden bg-sidebar p-12 text-sidebar-foreground lg:flex lg:flex-col"><Logo light /><div className="relative z-10 mt-auto max-w-lg pb-10"><p className="mb-5 font-mono text-[10px] uppercase tracking-[0.25em] text-sidebar-primary">Insurance, made legible</p><h1 className="font-serif text-5xl font-bold leading-[1.04] tracking-tight">A fairer path to <span className="text-sidebar-primary">cover.</span></h1><p className="mt-6 max-w-md text-base leading-relaxed text-sidebar-foreground/65">Aegisline gives people and the teams who protect them a clear view of risk, evidence, and every decision in between.</p><div className="mt-10 flex gap-8 border-t border-sidebar-border pt-5 text-xs text-sidebar-foreground/50"><span><strong className="block font-serif text-xl text-sidebar-foreground">01</strong>Transparent review</span><span><strong className="block font-serif text-xl text-sidebar-foreground">02</strong>Human oversight</span><span><strong className="block font-serif text-xl text-sidebar-foreground">03</strong>Secure by design</span></div></div><div className="absolute -right-24 top-24 size-72 rounded-full border border-sidebar-primary/20" /><div className="absolute -right-10 top-40 size-44 rounded-full border border-sidebar-primary/20" /></section>
    <section className="flex items-center justify-center p-6 md:p-12"><div className="w-full max-w-md"><div className="mb-12 lg:hidden"><Logo /></div>{children}<p className="mt-10 text-center text-xs text-muted-foreground">Aegisline protects your information with care. <Link href="/chat" className="font-semibold text-primary" data-testid="link-auth-help">Need help?</Link></p></div></section>
  </div>;
}

function Login() {
  const [, setLocation] = useLocation(); const login = useLogin(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: { email, password } }, { onSuccess: () => setLocation('/dashboard'), onError: () => setError('We could not sign you in. Check your email and password.') }); };
  return <AuthLayout mode="login"><div className="mb-10"><p className="mb-3 font-mono text-[10px] font-medium uppercase tracking-[0.22em] text-primary">Welcome back</p><h2 className="font-serif text-4xl font-bold tracking-tight">Good to see you.</h2><p className="mt-3 text-sm text-muted-foreground">Sign in to continue your insurance journey.</p></div><form onSubmit={submit} className="space-y-5"><label className="block text-sm font-semibold">Email address<input value={email} onChange={e => setEmail(e.target.value)} type="email" required placeholder="you@example.com" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" data-testid="input-email" /></label><label className="block text-sm font-semibold">Password<div className="relative mt-2"><input value={password} onChange={e => setPassword(e.target.value)} type="password" required placeholder="Your password" className="h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" data-testid="input-password" /><button type="button" className="absolute right-3 top-3 text-xs font-semibold text-primary" onClick={() => setPassword('')} data-testid="button-clear-password">Clear</button></div></label>{error && <p className="rounded-lg bg-rose-50 p-3 text-sm text-rose-700" data-testid="status-login-error">{error}</p>}<button disabled={login.isPending} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary font-semibold text-primary-foreground transition hover:brightness-110 disabled:opacity-60" data-testid="button-submit-login">{login.isPending ? 'Signing you in…' : 'Sign in'}<ArrowRight size={16} /></button></form><p className="mt-7 text-center text-sm text-muted-foreground">New to Aegisline? <Link href="/register" className="font-bold text-primary" data-testid="link-register">Create an account</Link></p></AuthLayout>;
}

function Register() {
  const [, setLocation] = useLocation(); const register = useRegister(); const [form, setForm] = useState({ name: '', email: '', password: '', role: 'customer' as 'customer' | 'underwriter' }); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); register.mutate({ data: form }, { onSuccess: () => setLocation('/dashboard'), onError: () => setError('We could not create your account. Please check your details.') }); };
  return <AuthLayout mode="register"><div className="mb-8"><p className="mb-3 font-mono text-[10px] font-medium uppercase tracking-[0.22em] text-primary">Start clearly</p><h2 className="font-serif text-4xl font-bold tracking-tight">Create your workspace.</h2><p className="mt-3 text-sm text-muted-foreground">Choose the view that fits how you work with insurance.</p></div><form onSubmit={submit} className="space-y-4"><label className="block text-sm font-semibold">Full name<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-input bg-card px-4 text-sm" placeholder="Your name" data-testid="input-name" /></label><label className="block text-sm font-semibold">Email address<input required type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-input bg-card px-4 text-sm" placeholder="you@example.com" data-testid="input-register-email" /></label><label className="block text-sm font-semibold">Password<input required minLength={8} type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-input bg-card px-4 text-sm" placeholder="8 characters minimum" data-testid="input-register-password" /></label><div><span className="block text-sm font-semibold">I am joining as</span><div className="mt-2 grid grid-cols-2 gap-2">{(['customer', 'underwriter'] as const).map(role => <button type="button" key={role} onClick={() => setForm({ ...form, role })} className={`rounded-xl border p-3 text-left text-sm ${form.role === role ? 'border-primary bg-secondary font-bold text-primary' : 'border-input text-muted-foreground'}`} data-testid={`button-role-${role}`}><span className="block capitalize">{role}</span><span className="mt-1 block text-[11px] font-normal opacity-70">{role === 'customer' ? 'Manage my cover' : 'Review applications'}</span></button>)}</div></div>{error && <p className="rounded-lg bg-rose-50 p-3 text-sm text-rose-700" data-testid="status-register-error">{error}</p>}<button disabled={register.isPending} className="mt-2 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary font-semibold text-primary-foreground disabled:opacity-60" data-testid="button-submit-register">{register.isPending ? 'Creating workspace…' : 'Create workspace'}<ArrowRight size={16} /></button></form><p className="mt-7 text-center text-sm text-muted-foreground">Already have access? <Link href="/login" className="font-bold text-primary" data-testid="link-login">Sign in</Link></p></AuthLayout>;
}

function SectionTitle({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: React.ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 font-mono text-[10px] font-medium uppercase tracking-[0.2em] text-primary">{eyebrow}</p>}<h1 className="font-serif text-3xl font-bold tracking-tight md:text-4xl" data-testid="text-page-title">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm text-muted-foreground">{detail}</p>}</div>{action}</div>;
}
function Metric({ label, value, sub, icon: Icon, tone = 'primary' }: { label: string; value: string | number; sub?: string; icon: React.ElementType; tone?: string }) {
  return <div className="rounded-2xl border border-border bg-card p-5" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-3 font-serif text-3xl font-bold tracking-tight">{value}</p></div><span className={`grid size-9 place-items-center rounded-xl ${tone === 'accent' ? 'bg-accent/25 text-primary' : 'bg-secondary text-primary'}`}><Icon size={18} /></span></div>{sub && <p className="mt-3 text-xs text-muted-foreground">{sub}</p>}</div>;
}
function ApplicationRow({ app }: { app: Application }) {
  return <Link href={`/applications/${app.id}`} className="group grid grid-cols-[1fr_auto] items-center gap-4 border-b border-border/70 py-4 last:border-0 sm:grid-cols-[1.3fr_1fr_0.8fr_auto] hover:bg-secondary/30" data-testid={`row-application-${app.id}`}><div><p className="font-semibold group-hover:text-primary">{app.applicantName}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{app.reference}</p></div><div className="hidden text-sm text-muted-foreground sm:block">{app.product}</div><div className="hidden sm:block"><StatusPill status={app.status} /></div><div className="text-right"><p className="text-sm font-bold">{money(app.coverageAmount)}</p><p className="mt-1 text-[11px] text-muted-foreground">{date(app.updatedAt)}</p></div></Link>;
}

function CustomerDashboard({ user }: { user: { name: string; email: string; role: string } }) {
  const q = useGetCustomerDashboard(); if (q.isLoading) return <PageLoader />; if (q.isError) return <ErrorState retry={() => q.refetch()} />; const d = q.data; const apps = d?.recentApplications || [];
  return <><SectionTitle eyebrow="Customer overview" title={`Good morning, ${user.name.split(' ')[0]}.`} detail="Your cover, your applications, and the next clear step." action={<Link href="/applications/new" className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="button-new-application"><Plus size={16} /> New application</Link>} /><div className="mb-6 rounded-2xl bg-sidebar p-6 text-sidebar-foreground md:p-8"><div className="max-w-xl"><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-sidebar-primary">Your next step</p><h2 className="mt-3 font-serif text-2xl font-bold">{d?.nextAction || 'Keep your applications moving.'}</h2><p className="mt-2 text-sm leading-relaxed text-sidebar-foreground/60">We will always tell you what we need, why we need it, and what happens next.</p><Link href="/applications" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-sidebar-primary" data-testid="link-view-applications">View your applications <ArrowRight size={15} /></Link></div><div className="mt-6 hidden items-end gap-2 md:flex"><div className="h-16 w-8 rounded-t-md bg-sidebar-primary/25" /><div className="h-24 w-8 rounded-t-md bg-sidebar-primary/45" /><div className="h-32 w-8 rounded-t-md bg-sidebar-primary" /><div className="ml-2 h-40 w-8 rounded-t-md border border-sidebar-primary/60" /></div></div><div className="grid gap-4 md:grid-cols-3"><Metric label="Active applications" value={d?.activeApplications ?? 0} sub="Across all products" icon={FileCheck2} /><Metric label="Approved cover" value={money(d?.approvedCoverage)} sub="Total annual protection" icon={ShieldCheck} tone="accent" /><Metric label="Last updated" value={apps[0] ? date(apps[0].updatedAt) : '—'} sub="Your most recent activity" icon={Clock3} /></div><div className="mt-8 rounded-2xl border border-border bg-card p-5 md:p-7"><div className="mb-3 flex items-center justify-between"><div><h2 className="font-serif text-xl font-bold">Recent applications</h2><p className="mt-1 text-sm text-muted-foreground">A clear record of where things stand.</p></div><Link href="/applications" className="text-xs font-bold text-primary" data-testid="link-all-applications">See all</Link></div>{apps.length ? apps.map(app => <ApplicationRow key={app.id} app={app} />) : <EmptyState title="No applications yet" detail="When you begin an application, it will appear here." action={<Link href="/applications/new" className="mt-5 inline-flex rounded-lg bg-primary px-4 py-2 text-sm font-bold text-primary-foreground" data-testid="button-empty-new">Start an application</Link>} />}</div></>;
}

function UnderwriterDashboard() {
  const q = useGetUnderwriterDashboard(); if (q.isLoading) return <PageLoader />; if (q.isError) return <ErrorState retry={() => q.refetch()} />; const d = q.data; return <><SectionTitle eyebrow="Underwriting desk" title="Make the next decision clear." detail="A focused view of work that needs an experienced eye." action={<Link href="/underwriter" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="button-open-queue"><LayoutList size={16} /> Open queue</Link>} /><div className="grid gap-4 md:grid-cols-4"><Metric label="In review" value={d?.inReview ?? 0} sub="Needs attention" icon={Clock3} /><Metric label="High risk" value={d?.highRisk ?? 0} sub="Review with care" icon={Activity} tone="accent" /><Metric label="Fraud signals" value={d?.fraudSignals ?? 0} sub="Evidence to inspect" icon={ShieldCheck} /><Metric label="Avg turnaround" value={`${d?.avgTurnaroundHours ?? 0}h`} sub="Last 30 days" icon={TrendingUp} /></div><div className="mt-8 grid gap-6 xl:grid-cols-[1.4fr_0.6fr]"><div className="rounded-2xl border border-border bg-card p-5 md:p-7"><div className="mb-3 flex items-center justify-between"><div><h2 className="font-serif text-xl font-bold">Recent queue activity</h2><p className="mt-1 text-sm text-muted-foreground">Applications entering your working set.</p></div><Link href="/underwriter" className="text-xs font-bold text-primary" data-testid="link-review-queue">View queue</Link></div>{d?.recentApplications?.length ? d.recentApplications.map(app => <ApplicationRow key={app.id} app={app} />) : <EmptyState title="Queue is clear" detail="New applications will appear here as they are ready for review." />}</div><div className="rounded-2xl bg-secondary p-6"><div className="mb-5 flex size-10 items-center justify-center rounded-xl bg-card text-primary"><Sparkles size={19} /></div><h2 className="font-serif text-xl font-bold">A human-readable desk</h2><p className="mt-3 text-sm leading-relaxed text-muted-foreground">Scores are signals, not verdicts. Open an application to see the evidence behind every recommendation.</p><Link href="/analytics" className="mt-6 inline-flex items-center gap-2 text-sm font-bold text-primary" data-testid="link-analytics">Explore portfolio <ArrowRight size={15} /></Link></div></div></>;
}

function Dashboard() {
  const [, setLocation] = useLocation();
  const q = useGetCurrentUser({ query: { queryKey: ['/api/auth/me'] } });
  useEffect(() => {
    if (q.isError) setLocation('/login');
  }, [q.isError, setLocation]);
  if (q.isLoading || q.isError || !q.data) return <Shell><PageLoader /></Shell>;
  const user = q.data;
  return <Shell user={user}>{user.role === 'underwriter' || user.role === 'admin' ? <UnderwriterDashboard /> : <CustomerDashboard user={user} />}</Shell>;
}

function Applications() {
  const q = useListApplications(); const [filter, setFilter] = useState(''); if (q.isLoading) return <Shell><PageLoader /></Shell>; if (q.isError) return <Shell><ErrorState retry={() => q.refetch()} /></Shell>; const apps = (q.data || []).filter(a => !filter || a.status.toLowerCase() === filter);
  return <Shell><SectionTitle eyebrow="Application history" title="Your applications" detail="Every application, with its status and next step." action={<Link href="/applications/new" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="button-applications-new"><Plus size={16} /> New application</Link>} /><div className="mb-4 flex flex-wrap items-center gap-2"><Filter size={15} className="mr-1 text-muted-foreground" /><button onClick={() => setFilter('')} className={`rounded-full px-3 py-1.5 text-xs font-bold ${!filter ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground'}`} data-testid="button-filter-all">All</button>{['draft', 'submitted', 'in review', 'approved', 'declined'].map(s => <button key={s} onClick={() => setFilter(s)} className={`rounded-full px-3 py-1.5 text-xs font-bold capitalize ${filter === s ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground'}`} data-testid={`button-filter-${s.replaceAll(' ', '-')}`}>{s}</button>)}</div><div className="rounded-2xl border border-border bg-card p-5 md:p-7">{apps.length ? <>{apps.map(app => <ApplicationRow key={app.id} app={app} />)}</> : <EmptyState title="No matching applications" detail="Try another status filter or start a new application." />}</div></Shell>;
}

function NewApplication() {
  const [, setLocation] = useLocation(); const create = useCreateApplication(); const [step, setStep] = useState(1); const [created, setCreated] = useState<Application | null>(null); const [form, setForm] = useState({ product: 'Home protection', coverageAmount: '250000', applicantName: '', applicantEmail: '', dateOfBirth: '', annualIncome: '', occupation: '', address: '', notes: '' });
  const update = (key: string, value: string) => setForm(f => ({ ...f, [key]: value }));
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { ...form, coverageAmount: Number(form.coverageAmount), annualIncome: form.annualIncome ? Number(form.annualIncome) : null, dateOfBirth: form.dateOfBirth || null, occupation: form.occupation || null, address: form.address || null, notes: form.notes || null } }, { onSuccess: app => { setCreated(app); setStep(3); } }); };
  return <Shell><SectionTitle eyebrow="New application" title="Tell us what you want to protect." detail="A few thoughtful details help us understand your situation. You can save at any point." /><div className="mb-8 flex max-w-2xl items-center gap-2">{['Your cover', 'About you', 'Documents'].map((label, i) => <div key={label} className="flex flex-1 items-center gap-2"><span className={`grid size-7 shrink-0 place-items-center rounded-full text-xs font-bold ${step > i + 1 ? 'bg-emerald-600 text-white' : step === i + 1 ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground'}`}>{step > i + 1 ? <Check size={14} /> : i + 1}</span><span className={`hidden text-xs font-bold sm:block ${step === i + 1 ? 'text-foreground' : 'text-muted-foreground'}`}>{label}</span>{i < 2 && <span className="h-px flex-1 bg-border" />}</div>)}</div>{step === 3 && created ? <ApplicationDocuments app={created} /> : <form onSubmit={submit} className="max-w-3xl rounded-2xl border border-border bg-card p-5 md:p-8">{step === 1 && <><h2 className="font-serif text-2xl font-bold">Choose your cover</h2><p className="mt-1 text-sm text-muted-foreground">We’ll use this to shape the right application path.</p><div className="mt-7 grid gap-3 sm:grid-cols-2">{['Home protection', 'Life protection', 'Travel protection', 'Income protection'].map(product => <button type="button" key={product} onClick={() => update('product', product)} className={`rounded-xl border p-4 text-left transition ${form.product === product ? 'border-primary bg-secondary' : 'border-input hover:border-primary/40'}`} data-testid={`button-product-${product.split(' ')[0].toLowerCase()}`}><span className="font-bold">{product}</span><span className="mt-1 block text-xs text-muted-foreground">A clear, tailored application</span></button>)}</div><label className="mt-7 block text-sm font-semibold">Coverage amount<input type="number" min="0" value={form.coverageAmount} onChange={e => update('coverageAmount', e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-4" data-testid="input-coverage-amount" /></label><div className="mt-8 flex justify-end"><button type="button" onClick={() => setStep(2)} className="inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground" data-testid="button-next-about">Continue <ArrowRight size={16} /></button></div></>}{step === 2 && <><button type="button" onClick={() => setStep(1)} className="mb-5 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground" data-testid="button-back-cover"><ArrowLeft size={14} /> Back</button><h2 className="font-serif text-2xl font-bold">A little about you</h2><p className="mt-1 text-sm text-muted-foreground">This information is used to assess your application fairly.</p><div className="mt-7 grid gap-5 sm:grid-cols-2"><label className="text-sm font-semibold">Full name<input required value={form.applicantName} onChange={e => update('applicantName', e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3" data-testid="input-applicant-name" /></label><label className="text-sm font-semibold">Email address<input required type="email" value={form.applicantEmail} onChange={e => update('applicantEmail', e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3" data-testid="input-applicant-email" /></label><label className="text-sm font-semibold">Date of birth<input type="date" value={form.dateOfBirth} onChange={e => update('dateOfBirth', e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3" data-testid="input-date-of-birth" /></label><label className="text-sm font-semibold">Annual income<input type="number" value={form.annualIncome} onChange={e => update('annualIncome', e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3" placeholder="Optional" data-testid="input-annual-income" /></label><label className="text-sm font-semibold">Occupation<input value={form.occupation} onChange={e => update('occupation', e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3" placeholder="Optional" data-testid="input-occupation" /></label><label className="text-sm font-semibold">Address<input value={form.address} onChange={e => update('address', e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3" placeholder="Optional" data-testid="input-address" /></label></div><label className="mt-5 block text-sm font-semibold">Anything else we should know?<textarea value={form.notes} onChange={e => update('notes', e.target.value)} className="mt-2 min-h-24 w-full rounded-xl border border-input bg-background p-3" placeholder="Optional context" data-testid="input-application-notes" /></label><div className="mt-8 flex justify-end"><button disabled={create.isPending} className="inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground disabled:opacity-60" data-testid="button-submit-application">{create.isPending ? 'Saving application…' : 'Save and add documents'} <ArrowRight size={16} /></button></div></>}</form>}</Shell>;
}

function ApplicationDocuments({ app }: { app: Application }) {
  const [, setLocation] = useLocation(); const docs = useListDocuments(app.id, { query: { queryKey: getListDocumentsQueryKey(app.id) } }); const submit = useSubmitApplication(); const [files, setFiles] = useState<Document[]>([]); const [uploading, setUploading] = useState(false); const [uploadError, setUploadError] = useState('');
  const addFiles = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = Array.from(e.target.files || []);
    if (!selected.length) return;
    setUploading(true); setUploadError('');
    try {
      const uploaded: Document[] = [];
      for (const file of selected) {
        const body = new FormData(); body.append('file', file);
        const response = await fetch(`/api/applications/${app.id}/documents/upload`, { method: 'POST', body, credentials: 'include' });
        if (!response.ok) throw new Error('Upload failed');
        uploaded.push(await response.json() as Document);
      }
      setFiles(prev => [...prev, ...uploaded]);
      void docs.refetch();
    } catch {
      setUploadError('One or more files could not be uploaded. Please try again.');
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };
  const submitApp = () => submit.mutate({ applicationId: app.id }, { onSuccess: () => setLocation(`/applications/${app.id}`) });
  return <div className="max-w-3xl rounded-2xl border border-border bg-card p-5 md:p-8"><div className="flex items-start justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-wider text-primary">{app.reference}</p><h2 className="mt-2 font-serif text-2xl font-bold">Add supporting documents</h2><p className="mt-1 text-sm text-muted-foreground">Documents help an underwriter verify what you’ve told us.</p></div><FileCheck2 className="text-primary" /></div><label className="mt-8 flex cursor-pointer flex-col items-center justify-center rounded-2xl border border-dashed border-primary/40 bg-secondary/50 px-6 py-12 text-center transition hover:bg-secondary" data-testid="dropzone-documents"><UploadCloud className="mb-3 text-primary" size={25} /><span className="font-bold">{uploading ? 'Uploading securely…' : 'Choose documents'}</span><span className="mt-1 text-xs text-muted-foreground">PDF, JPG, or PNG up to 10MB each</span><input type="file" multiple className="hidden" onChange={addFiles} disabled={uploading} data-testid="input-documents" /></label>{uploadError && <p className="mt-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-700" data-testid="status-upload-error">{uploadError}</p>}{(docs.data?.length || files.length) > 0 && <div className="mt-5 space-y-2">{[...(docs.data || []), ...files].filter((doc, i, all) => all.findIndex(item => item.id === doc.id) === i).map(doc => <div key={doc.id} className="flex items-center gap-3 rounded-xl border border-border p-3" data-testid={`row-document-${doc.id}`}><FileText size={17} className="text-primary" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{doc.name}</p><p className="text-[11px] text-muted-foreground">{Math.ceil(doc.size / 1024)} KB</p></div><span className="text-xs font-semibold text-emerald-700">{doc.status}</span></div>)}</div>}<div className="mt-8 flex flex-col-reverse justify-between gap-3 border-t border-border pt-5 sm:flex-row sm:items-center"><p className="text-xs text-muted-foreground">You can submit without documents and add them later.</p><button onClick={submitApp} disabled={submit.isPending || uploading} className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground disabled:opacity-60" data-testid="button-submit-for-review">{submit.isPending ? 'Submitting…' : 'Submit for review'} <ArrowRight size={16} /></button></div></div>;
}

function ApplicationDetailPage() {
  const { id = '' } = useParams<{ id: string }>(); const app = useGetApplication(id, { query: { enabled: !!id, queryKey: getGetApplicationQueryKey(id) } }); const decision = useGetDecision(id, { query: { enabled: !!id, queryKey: getGetDecisionQueryKey(id) } }); const history = useListStatusHistory(id, { query: { enabled: !!id, queryKey: getListStatusHistoryQueryKey(id) } }); const docs = useListDocuments(id, { query: { enabled: !!id, queryKey: getListDocumentsQueryKey(id) } }); const currentUser = useGetCurrentUser({ query: { queryKey: ['/api/auth/me'] } }); if (app.isLoading) return <Shell><PageLoader /></Shell>; if (app.isError || !app.data) return <Shell><ErrorState retry={() => app.refetch()} /></Shell>; const a = app.data; const canEdit = currentUser.data?.role === 'underwriter' || currentUser.data?.role === 'admin'; return <Shell user={currentUser.data}><Link href="/applications" className="mb-7 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary" data-testid="link-back-applications"><ArrowLeft size={14} /> All applications</Link><div className="mb-8 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-primary">{a.reference}</p><h1 className="mt-2 font-serif text-4xl font-bold tracking-tight" data-testid="text-application-name">{a.product}</h1><p className="mt-2 text-sm text-muted-foreground">{a.applicantName} · submitted {date(a.createdAt)}</p></div><StatusPill status={a.status} /></div><div className="grid gap-6 xl:grid-cols-[1.3fr_0.7fr]"><div className="space-y-6"><Timeline events={history.data || []} current={a.status} /><Explanation decision={decision.data} applicationId={id} editable={canEdit} /><Documents docs={docs.data || []} /></div><div className="space-y-6"><div className="rounded-2xl bg-sidebar p-6 text-sidebar-foreground"><p className="font-mono text-[10px] uppercase tracking-wider text-sidebar-primary">Coverage</p><p className="mt-3 font-serif text-3xl font-bold">{money(a.coverageAmount)}</p><p className="mt-1 text-sm text-sidebar-foreground/60">{a.product}</p><div className="mt-6 grid grid-cols-2 gap-3 border-t border-sidebar-border pt-5"><div><p className="text-[10px] uppercase text-sidebar-foreground/45">Applicant</p><p className="mt-1 text-sm font-semibold">{a.applicantName}</p></div><div><p className="text-[10px] uppercase text-sidebar-foreground/45">Updated</p><p className="mt-1 text-sm font-semibold">{date(a.updatedAt)}</p></div></div></div><div className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center gap-2"><Info size={16} className="text-primary" /><h2 className="font-serif text-lg font-bold">About this review</h2></div><p className="mt-3 text-sm leading-relaxed text-muted-foreground">Risk and fraud signals are reviewed alongside your information and documents. If we need anything else, we will tell you here.</p><Link href="/chat" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-primary" data-testid="link-detail-help">Ask the assistant <ArrowRight size={15} /></Link></div></div></div></Shell>;
}
function Timeline({ events, current }: { events: StatusEvent[]; current?: string }) {
  const items = events.length ? events : [{ id: 'current', status: current || 'submitted', label: current || 'Application received', occurredAt: new Date().toISOString(), actor: null }]; return <div className="rounded-2xl border border-border bg-card p-6 md:p-7"><h2 className="font-serif text-xl font-bold">Your application journey</h2><div className="mt-7 space-y-0">{items.map((event, i) => <div key={event.id} className="relative flex gap-4 pb-7 last:pb-0" data-testid={`event-status-${event.id}`}><div className="relative z-[1] grid size-8 shrink-0 place-items-center rounded-full border-4 border-card bg-primary text-primary-foreground">{i < items.length - 1 ? <Check size={12} /> : <Clock3 size={12} />}</div>{i < items.length - 1 && <div className="absolute left-4 top-8 h-full w-px bg-primary/25" />}<div><p className="text-sm font-bold capitalize">{event.label}</p><p className="mt-1 text-xs text-muted-foreground">{date(event.occurredAt)}{event.actor ? ` · ${event.actor}` : ''}</p></div></div>)}</div></div>;
}
function Explanation({ decision, applicationId, editable }: { decision?: Decision; applicationId?: string; editable?: boolean }) {
  if (!decision) return <div className="rounded-2xl border border-dashed border-border bg-card p-7"><div className="flex items-center gap-2 text-primary"><Activity size={17} /><h2 className="font-serif text-xl font-bold">Risk review is in progress</h2></div><p className="mt-3 text-sm leading-relaxed text-muted-foreground">Your application does not have a decision yet. When it does, we’ll show the factors and rationale here, not just a label.</p></div>;
  const update = useUpdateDecision(); const [recommendation, setRecommendation] = useState(decision.recommendation); const [rationaleText, setRationaleText] = useState(decision.rationale.join('\n')); useEffect(() => { setRecommendation(decision.recommendation); setRationaleText(decision.rationale.join('\n')); }, [decision]); const save = () => { if (!applicationId) return; update.mutate({ applicationId, data: { recommendation, rationale: rationaleText.split('\n').map(x => x.trim()).filter(Boolean) } }, { onSuccess: next => queryClient.setQueryData(getGetDecisionQueryKey(applicationId), next) }); };
  return <div className="rounded-2xl border border-border bg-card p-6 md:p-7"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="font-mono text-[10px] uppercase tracking-wider text-primary">Transparent decision</p>{editable ? <select value={recommendation} onChange={e => setRecommendation(e.target.value)} className="mt-2 rounded-lg border border-input bg-background px-2 py-1 font-serif text-xl font-bold" data-testid="select-decision-recommendation"><option>Approve</option><option>Decline</option><option>Refer for review</option></select> : <h2 className="mt-2 font-serif text-xl font-bold">{decision.recommendation}</h2>}</div><span className="rounded-lg bg-secondary px-3 py-2 text-xs font-bold capitalize text-primary">{decision.modelStatus}</span></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Score label="Risk score" score={decision.riskScore} band={decision.riskBand} /><Score label="Fraud score" score={decision.fraudScore} band={decision.fraudBand} /></div><div className="mt-6 border-t border-border pt-5"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Why this recommendation</p>{editable ? <><textarea value={rationaleText} onChange={e => setRationaleText(e.target.value)} className="mt-3 min-h-24 w-full rounded-xl border border-input bg-background p-3 text-sm leading-relaxed" data-testid="input-decision-rationale" /><button onClick={save} disabled={update.isPending} className="mt-3 rounded-lg bg-primary px-4 py-2 text-sm font-bold text-primary-foreground disabled:opacity-60" data-testid="button-save-decision">{update.isPending ? 'Saving…' : 'Save decision'}</button></> : <ul className="mt-3 space-y-2">{decision.rationale.map((r, i) => <li key={i} className="flex gap-2 text-sm leading-relaxed"><CheckCircle2 size={16} className="mt-0.5 shrink-0 text-emerald-600" />{r}</li>)}</ul>}</div></div>;
}
function Score({ label, score, band }: { label: string; score: number; band: string }) { return <div className="rounded-xl bg-secondary p-4"><div className="flex justify-between text-xs font-semibold"><span>{label}</span><span className="capitalize text-primary">{band}</span></div><div className="mt-3 flex items-center gap-3"><div className="h-2 flex-1 overflow-hidden rounded-full bg-card"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(score, 100)}%` }} /></div><span className="font-mono text-xs font-bold">{score}</span></div></div>; }
function Documents({ docs }: { docs: Document[] }) { return <div className="rounded-2xl border border-border bg-card p-6 md:p-7"><div className="flex items-center justify-between"><h2 className="font-serif text-xl font-bold">Documents</h2><span className="text-xs text-muted-foreground">{docs.length} uploaded</span></div>{docs.length ? <div className="mt-4 divide-y divide-border">{docs.map(doc => <div className="flex items-center gap-3 py-3" key={doc.id} data-testid={`detail-document-${doc.id}`}><FileText size={17} className="text-primary" /><span className="flex-1 truncate text-sm font-semibold">{doc.name}</span><span className="text-xs text-muted-foreground">{Math.ceil(doc.size / 1024)} KB</span><CheckCircle2 size={15} className="text-emerald-600" /></div>)}</div> : <p className="mt-4 text-sm text-muted-foreground">No documents have been added yet.</p>}</div>; }

function UnderwriterQueue() {
  const [status, setStatus] = useState(''); const q = useListUnderwriterApplications(status ? { status } : undefined); if (q.isLoading) return <Shell><PageLoader /></Shell>; if (q.isError) return <Shell><ErrorState retry={() => q.refetch()} /></Shell>; const apps = q.data || []; return <Shell><SectionTitle eyebrow="Review queue" title="Applications that need you." detail="Start with the evidence. Finish with a decision you can stand behind." /><div className="mb-6 grid gap-4 md:grid-cols-3"><Metric label="Working set" value={apps.length} sub="Applications in this view" icon={LayoutList} /><Metric label="Average risk" value={apps.length ? Math.round(apps.reduce((n, a) => n + a.riskScore, 0) / apps.length) : 0} sub="Across visible applications" icon={Activity} tone="accent" /><Metric label="High attention" value={apps.filter(a => a.riskScore > 65 || a.fraudScore > 65).length} sub="Risk or fraud signal above 65" icon={AlertTriangle} /></div><div className="mb-4 flex items-center gap-2"><Filter size={15} className="text-muted-foreground" />{['', 'submitted', 'in review', 'approved', 'declined'].map(s => <button key={s || 'all'} onClick={() => setStatus(s)} className={`rounded-full px-3 py-1.5 text-xs font-bold capitalize ${status === s ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground'}`} data-testid={`button-queue-filter-${s || 'all'}`}>{s || 'All'}</button>)}</div><div className="rounded-2xl border border-border bg-card p-5 md:p-7">{apps.length ? apps.map(app => <Link href={`/applications/${app.id}`} key={app.id} className="grid gap-3 border-b border-border/70 py-5 last:border-0 md:grid-cols-[1.4fr_0.8fr_0.7fr_0.7fr_auto] md:items-center" data-testid={`row-queue-${app.id}`}><div><p className="font-semibold">{app.applicantName}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{app.reference} · {app.product}</p></div><div><p className="text-[10px] uppercase tracking-wider text-muted-foreground">Risk</p><p className={`mt-1 font-mono text-sm font-bold ${app.riskScore > 65 ? 'text-rose-700' : 'text-foreground'}`}>{app.riskScore} <span className="font-sans text-xs font-normal text-muted-foreground">/ 100</span></p></div><div><p className="text-[10px] uppercase tracking-wider text-muted-foreground">Fraud</p><p className={`mt-1 font-mono text-sm font-bold ${app.fraudScore > 65 ? 'text-rose-700' : 'text-foreground'}`}>{app.fraudScore} <span className="font-sans text-xs font-normal text-muted-foreground">/ 100</span></p></div><StatusPill status={app.status} /><ArrowRight size={16} className="text-muted-foreground" /></Link>) : <EmptyState title="No applications in this view" detail="Change your filter to see more of the review queue." />}</div></Shell>;
}

function Analytics() {
  const q = useGetAnalytics(); if (q.isLoading) return <Shell><PageLoader /></Shell>; if (q.isError) return <Shell><ErrorState retry={() => q.refetch()} /></Shell>; const a = q.data; const max = Math.max(...(a?.monthlyTrend || []).map(x => x.applications), 1); return <Shell><SectionTitle eyebrow="Portfolio intelligence" title="See the shape of your book." detail="A grounded view of volume, decisions, and risk signals over time." action={<button className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-bold" onClick={() => q.refetch()} data-testid="button-refresh-analytics"><Activity size={16} /> Refresh data</button>} /><div className="grid gap-4 md:grid-cols-4"><Metric label="Monthly volume" value={a?.monthlyVolume ?? 0} sub="Current reporting period" icon={BarChart3} /><Metric label="Approval rate" value={`${a?.approvalRate ?? 0}%`} sub="Of decided applications" icon={CheckCircle2} tone="accent" /><Metric label="Fraud rate" value={`${a?.fraudRate ?? 0}%`} sub="Flagged for review" icon={ShieldCheck} /><Metric label="Average risk" value={a?.averageRiskScore ?? 0} sub="Portfolio signal" icon={Activity} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.4fr_0.6fr]"><div className="rounded-2xl border border-border bg-card p-6 md:p-8"><div className="flex items-start justify-between"><div><h2 className="font-serif text-xl font-bold">Application volume</h2><p className="mt-1 text-sm text-muted-foreground">Applications, approvals, and declines by month.</p></div><span className="rounded-lg bg-secondary px-2 py-1 font-mono text-[10px] text-primary">LIVE DATA</span></div><div className="mt-10 flex h-56 items-end gap-2 border-b border-border sm:gap-5">{(a?.monthlyTrend || []).map(item => <div className="flex flex-1 flex-col items-center gap-2" key={item.month} data-testid={`chart-month-${item.month}`}><div className="flex h-44 w-full items-end justify-center gap-1"><div className="w-1/3 rounded-t bg-primary" style={{ height: `${Math.max(4, item.applications / max * 100)}%` }} /><div className="w-1/3 rounded-t bg-accent" style={{ height: `${Math.max(4, item.approved / max * 100)}%` }} /></div><span className="font-mono text-[10px] text-muted-foreground">{item.month}</span></div>)}</div><div className="mt-4 flex gap-5 text-xs text-muted-foreground"><span className="flex items-center gap-2"><i className="size-2 rounded-full bg-primary" /> Applications</span><span className="flex items-center gap-2"><i className="size-2 rounded-full bg-accent" /> Approved</span></div></div><div className="rounded-2xl border border-border bg-card p-6 md:p-8"><h2 className="font-serif text-xl font-bold">Status mix</h2><p className="mt-1 text-sm text-muted-foreground">Where applications are today.</p><div className="mt-7 space-y-5">{(a?.statusBreakdown || []).map(item => <div key={item.label} data-testid={`bar-status-${item.label}`}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{item.label}</span><span className="font-mono text-muted-foreground">{item.value}</span></div><div className="h-2 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(item.value, 100)}%` }} /></div></div>)}</div></div></div></Shell>;
}

function Chat() {
  const send = useSendChatMessage(); const [input, setInput] = useState(''); const [messages, setMessages] = useState<{ role: 'assistant' | 'user'; text: string; source?: string; disclaimer?: string }[]>([{ role: 'assistant', text: 'I can help explain policy language, application steps, and what supporting evidence usually means. I cannot make or change an underwriting decision.', source: 'Aegisline policy guidance', disclaimer: 'Guidance is informational and does not replace your policy documents or an underwriter.' }]);
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (!input.trim()) return; const text = input.trim(); setInput(''); setMessages(m => [...m, { role: 'user', text }]); send.mutate({ data: { message: text, context: 'insurance policy guidance' } }, { onSuccess: r => setMessages(m => [...m, { role: 'assistant', text: r.message, source: r.source, disclaimer: r.disclaimer }]), onError: () => setMessages(m => [...m, { role: 'assistant', text: 'I am having trouble reaching the guidance service. Please try again shortly.' }]) }); };
  return <Shell><SectionTitle eyebrow="Policy assistant" title="Ask a clear question." detail="A helpful starting point for understanding insurance. For decisions about your application, your underwriter has the final word." /><div className="mx-auto max-w-3xl overflow-hidden rounded-2xl border border-border bg-card"><div className="flex items-center gap-3 border-b border-border bg-secondary/50 p-5"><span className="grid size-10 place-items-center rounded-xl bg-primary text-primary-foreground"><Bot size={20} /></span><div><p className="font-semibold">Aegisline assistant</p><p className="text-xs text-muted-foreground">Policy guidance · not underwriting advice</p></div><span className="ml-auto size-2 rounded-full bg-emerald-500" /></div><div className="min-h-[420px] space-y-5 p-5 md:p-8">{messages.map((m, i) => <div key={i} className={`flex gap-3 ${m.role === 'user' ? 'flex-row-reverse' : ''}`} data-testid={`chat-message-${i}`}><span className={`grid size-8 shrink-0 place-items-center rounded-full text-xs font-bold ${m.role === 'assistant' ? 'bg-secondary text-primary' : 'bg-sidebar text-sidebar-primary'}`}>{m.role === 'assistant' ? <Bot size={15} /> : <UserRound size={15} />}</span><div className={`max-w-[80%] rounded-2xl p-4 text-sm leading-relaxed ${m.role === 'assistant' ? 'rounded-tl-sm bg-secondary' : 'rounded-tr-sm bg-primary text-primary-foreground'}`}><p>{m.text}</p>{m.source && <div className="mt-4 border-t border-primary/15 pt-3 text-[11px] text-muted-foreground"><span className="font-bold">Source:</span> {m.source}<br /><span className="font-bold">Note:</span> {m.disclaimer}</div>}</div></div>)}{send.isPending && <div className="flex items-center gap-3 text-sm text-muted-foreground" data-testid="status-chat-loading"><span className="grid size-8 place-items-center rounded-full bg-secondary"><Bot size={15} /></span><span className="animate-pulse">Reviewing policy guidance…</span></div>}</div><form onSubmit={submit} className="flex items-center gap-2 border-t border-border p-4"><button type="button" className="grid size-10 place-items-center rounded-xl text-muted-foreground hover:bg-secondary" data-testid="button-attach-chat"><Paperclip size={18} /></button><input value={input} onChange={e => setInput(e.target.value)} placeholder="For example: What does a deductible mean?" className="h-11 flex-1 bg-transparent px-2 text-sm outline-none" data-testid="input-chat-message" /><button disabled={send.isPending || !input.trim()} className="grid size-10 place-items-center rounded-xl bg-primary text-primary-foreground disabled:opacity-40" data-testid="button-send-chat"><Send size={17} /></button></form></div></Shell>;
}

function AppRouter() {
  return <Switch><Route path="/login" component={Login} /><Route path="/register" component={Register} /><Route path="/dashboard" component={Dashboard} /><Route path="/applications/new" component={NewApplication} /><Route path="/applications" component={Applications} /><Route path="/applications/:id" component={ApplicationDetailPage} /><Route path="/underwriter" component={UnderwriterQueue} /><Route path="/analytics" component={Analytics} /><Route path="/chat" component={Chat} /><Route path="/" component={Dashboard} /><Route component={NotFound} /></Switch>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppRouter /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;